import {deriveInsights} from './insights.mjs';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paragraph=value=>value?`<p>${esc(value)}</p>`:'';
function sourceLink(url){const parsed=new URL(url);if(parsed.protocol!=='https:')throw new Error('Invalid evidence URL');return `<a rel="noreferrer" href="${esc(url)}">${esc(url)}</a>`;}
const labels={'detected':'Variant detected','not-detected':'Selected variant not detected','missing':'Not in file','no-call':'No call reported','unsupported':'Outside supported rules'};
// Export from the current parser result, recomputing implications rather than trusting rendered text.
export function readableReport(result,{synthetic=false,createdAt=new Date()}={}){
 const insights=deriveInsights(result);
 const cards=insights.cards.map(card=>`<article><p class="eyebrow">${esc(card.medications.join(' · '))}</p><h3>${esc(card.heading)}</h3>${paragraph(card.body)}<h4>Reported basis</h4>${card.trace.basis.map(b=>paragraph(`${b.gene} · ${b.marker} · ${b.reportedCall}${b.codingName?` · Coding-DNA: ${b.codingName}; genomic: ${b.genomicSubstitution}. ${b.orientation}`:''}`)).join('')}${paragraph(card.trace.trigger)}${paragraph(card.trace.limitation)}<h4>Evidence</h4>${paragraph(card.trace.source.locator)}${sourceLink(card.trace.source.url)}${card.trace.source.updateNotice?`<aside><strong>Evidence update</strong>${paragraph(card.trace.source.updateNotice.summary)}${sourceLink(card.trace.source.updateNotice.url)}</aside>`:''}<p class="technical">Rule: ${esc(card.trace.ruleId)}<br>Source SHA-256: ${esc(card.trace.source.sha256)}</p></article>`).join('');
 return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"><title>Context — ${synthetic?'Synthetic example':'Selected-marker report'}</title><style>
 *{box-sizing:border-box}body{margin:0;background:#f6f4ee;color:#223a30;font:16px/1.6 system-ui,sans-serif}main{max-width:820px;margin:auto;padding:48px 28px}header{border-bottom:2px solid;padding-bottom:24px}h1,h2,h3{font-family:Georgia,serif;font-weight:400;line-height:1.18}h1{font-size:40px;margin:12px 0}h2{font-size:28px;margin-top:40px}h3{font-size:24px}h4{margin-bottom:6px}.eyebrow{font-size:12px;letter-spacing:.08em;text-transform:uppercase}.notice,aside{border-left:3px solid #8d593d;padding:8px 18px;background:#eeebe2}.technical,footer{font-size:12px;color:#4a584f;overflow-wrap:anywhere}article{border-top:1px solid #b8bcb2;padding:24px 0}a{color:inherit;overflow-wrap:anywhere}table{width:100%;border-collapse:collapse;font-size:14px}th,td{text-align:left;padding:10px 8px;border-bottom:1px solid #c9ccc2;vertical-align:top}th:first-child,td:first-child{padding-left:0}.coverage{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.coverage p{border-top:1px solid #b8bcb2;padding-top:12px}footer{margin-top:36px;border-top:1px solid;padding-top:16px}@media(max-width:520px){main{padding:24px 18px}h1{font-size:32px}.coverage{grid-template-columns:1fr;gap:0}th,td{padding:9px 4px;font-size:12px}}@media print{@page{margin:18mm}body{background:white;color:#17251d}main{max-width:none;padding:0}h2,h3,h4{break-after:avoid}tr,.notice,aside{break-inside:avoid}thead{display:table-header-group}.screen-only{display:none}a{text-decoration:none}}
 </style></head><body><main><header><p class="eyebrow">Context / ${synthetic?'Synthetic example — not a person’s result':'Selected-marker review'}</p><h1>Genetics &amp; medication</h1><p>Report saved ${esc(createdAt.toISOString().slice(0,10))} (UTC). Interpretation uses captured, dated evidence.</p></header><div class="notice"><strong>Educational report · Not a clinical test</strong><p>Selected markers cannot establish a complete genotype, metabolizer status or medication suitability. Consumer raw data can contain errors. Clinical confirmation is needed before findings inform care. Don’t start, stop or change medication based on this report.</p></div><p class="screen-only">This document opens offline. Use your browser’s Print menu to print or save a PDF. It contains sensitive genetic findings; choose where you save or share it.</p><h2>Coverage comes first</h2><p>${esc(result.covered)} / ${esc(result.findings.length)} selected markers have interpretable calls. Build 37 · Positive strand. This is not whole-gene coverage.</p><div class="coverage">${insights.geneCoverage.map(g=>`<p><strong>${esc(g.gene)}</strong><br>${g.called} / ${g.assessed} selected markers read<br>${g.unresolved.length} unresolved</p>`).join('')}</div><h2>${esc(insights.title)}</h2>${paragraph(insights.explanation)}${paragraph(insights.interactionNote)}${cards}<h2>Next conversation</h2>${paragraph(insights.nextStep)}<h2>All assessed calls</h2><p>Missing and reference calls do not establish normal function or drug safety. Genes and variants outside this list were not assessed.</p><table><thead><tr><th>Gene / marker</th><th>Reported call</th><th>Finding</th></tr></thead><tbody>${result.findings.map(f=>`<tr><td>${esc(f.gene)}<br>${esc(f.id)}</td><td>${esc(f.genotype??'—')}</td><td>${esc(labels[f.state])}</td></tr>`).join('')}</tbody></table><footer><p>Selected-marker research prototype. No independent clinical validation. No name, original filename or unassessed raw records are included. ${synthetic?'All input data in this example is invented.':''}</p><p>Marker rules: ${esc(result.ruleVersion)}<br>Implication rules: ${esc(insights.version??insights.ruleVersion)}<br>Marker evidence manifest SHA-256: ${esc(result.evidence.manifestSha256)}</p><p>The separate JSON export supports technical replay. Neither export authenticates the original assay.</p></footer></main></body></html>`;
}
